<?php
namespace App\Controllers; use App\Helpers\{Csrf,Flash,View,Auth,Settings}; use App\Middlewares\AuthMiddleware; use App\Repositories\ProductRepository; use App\Config\Database;
final class CartController {
 public function show():void{$items=$this->items();View::render('cliente/cart',['title'=>'Mi carrito','items'=>$items,'totals'=>$this->totals($items)]);}
 public function add():void{Csrf::validate();$id=(int)($_POST['product_id']??0);$q=max(1,(int)($_POST['quantity']??1));$p=(new ProductRepository())->find($id);if(!$p||$p['status']!=='ACTIVE'){Flash::set('error','Producto no disponible.');header('Location: /catalog');exit;}$_SESSION['cart'][$id]=min((int)$p['stock'],($_SESSION['cart'][$id]??0)+$q);Flash::set('success','Producto agregado al carrito.');header('Location: '.($_SERVER['HTTP_REFERER'] ?? '/cart'));}
 public function update():void{Csrf::validate();foreach($_POST['qty']??[] as $id=>$q){$q=(int)$q;if($q<=0)unset($_SESSION['cart'][(int)$id]);else $_SESSION['cart'][(int)$id]=$q;}Flash::set('success','Carrito actualizado.');header('Location: /cart');}
 public function checkout():void{AuthMiddleware::handle();Csrf::validate();$items=$this->items();if(!$items){Flash::set('error','Tu carrito está vacío.');header('Location: /cart');exit;}$pdo=Database::connection();$pdo->beginTransaction();try{$uid=(int)Auth::user()['id'];$subtotal=0;foreach($items as $i){if($i['quantity']>$i['stock'])throw new \RuntimeException('Stock insuficiente para '.$i['name']);$subtotal+=$i['price']*$i['quantity'];}$earned=(int)floor($subtotal*Settings::pointsPerUsd());$discount=0;$spent=0;$rewardId=(int)($_POST['reward_id']??0);if($rewardId){$s=$pdo->prepare("SELECT * FROM rewards WHERE id=? AND status='ACTIVE'");$s->execute([$rewardId]);$r=$s->fetch();$u=Auth::user();if($r && (int)$u['points_balance'] >= (int)$r['points_required']){$spent=(int)$r['points_required'];$discount=round($subtotal*((float)$r['discount_percent']/100),2);}}
 $total=max(0,$subtotal-$discount);$statusId=(int)$pdo->query("SELECT id FROM order_statuses WHERE name='PENDIENTE' LIMIT 1")->fetchColumn();$s=$pdo->prepare('INSERT INTO orders(user_id,status_id,subtotal,discount,total,points_earned,points_spent) VALUES(?,?,?,?,?,?,?)');$s->execute([$uid,$statusId,$subtotal,$discount,$total,$earned,$spent]);$oid=(int)$pdo->lastInsertId();$oi=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,subtotal) VALUES(?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');foreach($items as $i){$oi->execute([$oid,$i['id'],$i['name'],$i['price'],$i['quantity'],$i['price']*$i['quantity']]);$stock->execute([$i['quantity'],$i['id'],$i['quantity']]);if($stock->rowCount()!==1)throw new \RuntimeException('El stock cambió durante la compra.');}
 if($spent>0){$pdo->prepare('UPDATE users SET points_balance=points_balance-? WHERE id=?')->execute([$spent,$uid]);$pdo->prepare("INSERT INTO point_movements(user_id,order_id,type,points,description) VALUES(?,?,'REDEEM',?,?)")->execute([$uid,$oid,-$spent,'Canje de recompensa']);$pdo->prepare('INSERT INTO reward_redemptions(user_id,reward_id,order_id,points_spent,discount_amount) VALUES(?,?,?,?,?)')->execute([$uid,$rewardId,$oid,$spent,$discount]);}
 if($earned>0){$pdo->prepare('UPDATE users SET points_balance=points_balance+? WHERE id=?')->execute([$earned,$uid]);$pdo->prepare("INSERT INTO point_movements(user_id,order_id,type,points,description) VALUES(?,?,'EARN',?,?)")->execute([$uid,$oid,$earned,'Puntos por compra']);}
 $pdo->commit();$_SESSION['cart']=[];Flash::set('success',"Pedido #$oid creado. Ganaste $earned puntos.");header('Location: /profile');}catch(\Throwable $e){$pdo->rollBack();Flash::set('error',$e->getMessage());header('Location: /cart');}}
 private function items():array{$repo=new ProductRepository();$out=[];foreach($_SESSION['cart']??[] as $id=>$q){if($p=$repo->find((int)$id)){$p['quantity']=(int)$q;$out[]=$p;}}return $out;}
 private function totals(array $items):array{$subtotal=0;foreach($items as $i)$subtotal+=(float)$i['price']*$i['quantity'];$rewards=[];if(Auth::check()){$u=Auth::user();$s=Database::connection()->prepare("SELECT * FROM rewards WHERE status='ACTIVE' AND points_required<=? ORDER BY points_required");$s->execute([$u['points_balance']]);$rewards=$s->fetchAll();}return ['subtotal'=>$subtotal,'rewards'=>$rewards];}
}
